import{_ as a,o as t,c as o,a2 as c}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/BAR-CHART.md","filePath":"manual-en/BAR-CHART.md","lastUpdated":1785684581000}'),s={name:"manual-en/BAR-CHART.md"};function r(n,e,i,d,h,p){return t(),o("div",null,[...e[0]||(e[0]=[c(`<h4 id="_15-4-3-bar-chart" tabindex="-1">15.4.3 Bar Chart <a class="header-anchor" href="#_15-4-3-bar-chart" aria-label="Permalink to &quot;15.4.3 Bar Chart&quot;">​</a></h4><p>The subcommand <code>BAR</code> produces a bar chart. This subcommand requires that a count-function be specified (with no arguments) or a summary-function with a variable var1 in parentheses. Following the summary or count function, the keyword <code>BY</code> should be specified and then a catagorical variable, var2. The values of the variable var2 determine the labels of the bars to be plotted. Optionally a second categorical variable var3 may be specified in which case a clustered (grouped) bar chart is produced.</p><p>Valid count functions are</p><p><code>COUNT</code></p><p>The weighted counts of the cases in each category.</p><p><code>PCT</code></p><p>The weighted counts of the cases in each category expressed as a percentage of the total weights of the cases.</p><p><code>CUFREQ</code></p><p>The cumulative weighted counts of the cases in each category.</p><p><code>CUPCT</code></p><p>The cumulative weighted counts of the cases in each category expressed as a percentage of the total weights of the cases.</p><p>The summary function is applied to var1 across all cases in each category. The recognised summary functions are:</p><p><code>SUM</code></p><p>The sum.</p><p><code>MEAN</code></p><p>The arithmetic mean.</p><p><code>MAXIMUM</code></p><p>The maximum value.</p><p><code>MINIMUM</code></p><p>The minimum value.</p><p>The following examples assume a dataset which is the results of a survey. Each respondent has indicated annual income, their sex and city of residence. One could create a bar chart showing how the mean income varies between of residents of different cities, thus:</p><pre><code>GRAPH  /BAR  = MEAN(income) BY city.
</code></pre><p>This can be extended to also indicate how income in each city differs between the sexes.</p><pre><code>GRAPH  /BAR  = MEAN(income) BY city BY sex.
</code></pre><p>One might also want to see how many respondents there are from each city. This can be achieved as follows:</p><pre><code>GRAPH  /BAR  = COUNT BY city.
</code></pre><p>Bar charts can also be produced using the <a href="./FREQUENCIES">FREQUENCIES</a> and <a href="./CROSSTABS">CROSSTABS</a> commands.</p>`,27)])])}const m=a(s,[["render",r]]);export{u as __pageData,m as default};
